  const args = [
    // Format selector: prefer DASH (separate video+audio), fallback to progressive MP4
    "-f", "bv*[ext=mp4]+ba[ext=m4a]/b[ext=mp4]",

    // Merge output to single MP4 file (requires ffmpeg)
    "--merge-output-format", "mp4",

