3. **Added resumable download function (lines 1240-1478)**:
```javascript
function startResumableDownload(id, url, playerCommand) {
  const outputFile = path.join(tmpdir(), `youtube-${id}.mp4`);

  const args = [
    "-f", "18/bv*[ext=mp4][protocol!=m3u8]+ba[ext=m4a][protocol!=m3u8]/b[ext=mp4][protocol!=m3u8]",
    "--merge-output-format", "mp4",
    "--continue",      // Resume support
    "--newline",       // Structured progress output
    "--no-update",
    "-o", outputFile,
    url
  ];

  const proc = spawn("yt-dlp", args);

  activeDownloads.set(id, {
    process: proc,
    progress: 0,
    filePath: outputFile,
    lastUpdate: Date.now(),
    url: url,
    playerPid: null
  });

  // Parse progress from stdout
  proc.stdout.on("data", data => {
    const text = data.toString();
    const match = text.match(/(\d+\.\d+)%/);
    if (match) {
      const percent = parseFloat(match[1]);
      const entry = activeDownloads.get(id);
      if (entry) {
        entry.progress = percent;
        entry.lastUpdate = Date.now();
      }
    }
  });

  // Progressive playback - launch player when threshold reached
  const MIN_PLAYABLE_SIZE = 5 * 1024 * 1024; // 5MB
  let playerStarted = false;

  const pollInterval = setInterval(() => {
    if (!existsSync(outputFile)) return;
    const size = statSync(outputFile).size;

    if (size > MIN_PLAYABLE_SIZE && !playerStarted) {
      const playerProc = spawn(playerCommand, [
        "--force-seekable=yes",
        "--cache=yes",
        "--cache-secs=20",
        outputFile
      ], {
        detached: true,
        stdio: "ignore"
      });

      playerProc.unref();

      const entry = activeDownloads.get(id);
      if (entry) {
        entry.playerPid = playerProc.pid;
      }

      playerStarted = true;
    }
  }, 1000);

  proc.on("close", () => {
    clearInterval(pollInterval);
    activeDownloads.delete(id);
  });

  return outputFile;
}
```

4. **Added stall detection watchdog (lines 1707-1760)**:
```javascript
setInterval(() => {
  const now = Date.now();

  for (const [id, entry] of activeDownloads.entries()) {
    const timeSinceUpdate = now - entry.lastUpdate;

    if (timeSinceUpdate > 30000) {
      console.warn(`[STALL DETECTED] Download ${id} stalled`);
      entry.process.kill("SIGTERM");
      activeDownloads.delete(id);
    }
  }
}, 10000);
```

